const auth = $input.first().json;

// api.authorize's terminal nodes don't return requestId, so read it from the
// gate's own trigger input.
const requestId = $('When Executed by Another Workflow').first().json.requestId ?? null;

if (auth.authorized === true) {
  return [{
    json: {
      authorized: true,
      customer: auth.customer ?? null,
      requestId
    }
  }];
}

const code = String(auth.reason ?? 'UNAUTHORIZED');
const statusCode = Number(auth.status) === 403 ? 403 : 401;

const messages = {
  UNAUTHORIZED: 'Authentication failed.',
  CUSTOMER_NOT_FOUND: 'The API key is not valid or has been revoked.',
  CUSTOMER_ID_MISMATCH: 'The API key is valid, but the customer ID does not match.',
  FORBIDDEN: 'The API key does not have the required scope.'
};

return [{
  json: {
    authorized: false,
    statusCode,
    requestId,
    responseBody: {
      error: {
        code,
        message: messages[code] ?? 'Authorization failed.',
        retryable: false,
        requestId,
        details: []
      }
    }
  }
}];
